var D=[{"alt":[],"cls":"Warden (2014)","name":"Stoneheart Defender (2014)","src":"tvss14","arr":[[3,"Roots of Rock","When you use Warden's Grasp, rocky roots grow from your feet. Until the start of your next turn you have a +2 bonus to AC. Also, until you move, hostile actions, spells and effects cannot shove or push you from your spot unless you allow it. You have Advantage on Strength saving throws against being knocked Prone, you cannot slip or fall from ledges, and you are immune to the Fly, Levitate and Telekinesis spells."],[6,"Earthshatter","You can use Warden's Grasp as an action instead of a Bonus Action. If you do, each creature it affects makes a Strength saving throw (DC 8 + your Proficiency Bonus + your Strength modifier) or falls Prone. You can do this a number of times equal to your Strength modifier, and you regain all uses when you finish a Long Rest."],[13,"Mettle","When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Immortal Mountain","As an action you wrap yourself in stone for 1 minute. While it lasts: Bludgeoning, Piercing and Slashing damage you take is reduced by 5; you gain the effects of Roots of Rock for the whole duration; and as you move you can upend the ground, leaving a 5-foot-wide trail of difficult terrain behind you. After you use this, you cannot use it again until you finish a Long Rest."]],"full":{"Stoneheart Defender (2014)|Roots of Rock":"When you use Warden's Grasp, rocky roots grow from your feet. Until the start of your next turn you have a +2 bonus to AC. Also, until you move, hostile actions, spells and effects cannot shove or push you from your spot unless you allow it. You have Advantage on Strength saving throws against being knocked Prone, you cannot slip or fall from ledges, and you are immune to the Fly, Levitate and Telekinesis spells.","Stoneheart Defender (2014)|Earthshatter":"You can use Warden's Grasp as an action instead of a Bonus Action. If you do, each creature it affects makes a Strength saving throw (DC 8 + your Proficiency Bonus + your Strength modifier) or falls Prone. You can do this a number of times equal to your Strength modifier, and you regain all uses when you finish a Long Rest.","Stoneheart Defender (2014)|Mettle":"When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure.","Stoneheart Defender (2014)|Immortal Mountain":"As an action you wrap yourself in stone for 1 minute. While it lasts: Bludgeoning, Piercing and Slashing damage you take is reduced by 5; you gain the effects of Roots of Rock for the whole duration; and as you move you can upend the ground, leaving a 5-foot-wide trail of difficult terrain behind you. After you use this, you cannot use it again until you finish a Long Rest."},"auto":[],"lu":[{"src":"sub","owner":"Stoneheart Defender (2014)","feature":"Earthshatter","n":"Earthshatter","lvl":6,"max":"mod:STR","reset":"long","tag":"Action. Prone on a failed save"},{"src":"sub","owner":"Stoneheart Defender (2014)","feature":"Immortal Mountain","n":"Immortal Mountain","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Stoneheart Defender (2014)|Earthshatter":[["action",""]],"sub|Stoneheart Defender (2014)|Immortal Mountain":[["action",""]]},"cantrips":[],"pick":[],"fx":[[6,"Earthshatter",{"notes":[["Note","Earthshatter: Warden's Grasp as an action. Creatures in it make a Strength save or fall Prone"]]}],[13,"Mettle",{"notes":[["Note","Mettle: a successful Constitution save against half-damage effects means no damage"]]}]],"spab":""}];
